-- Migrate Noites Brasileiras and Secrets of New York to the official V5SN card IDs.
-- Apply with the server stopped.
-- Existing history is retained; only events generated by this migration are removed.

CREATE TEMPORARY TABLE v5sn_ids (
    old_id INT PRIMARY KEY, new_id INT NOT NULL UNIQUE,
    card_name VARCHAR(250) NOT NULL, card_set VARCHAR(64) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
