SET @v5sn_deck_history_start = (SELECT COALESCE(MAX(id),0) FROM deck_card_history);
SET @v5sn_collection_history_start = (SELECT COALESCE(MAX(id),0) FROM collection_card_history);

-- V1.0.70 left NB3 history referencing IDs later reused by V5SN.
-- Its surviving earlier events belong to NB3, not to the new products.
CREATE TEMPORARY TABLE v5sn_nb3_ids (old_id INT PRIMARY KEY, new_id INT NOT NULL) ENGINE=InnoDB;
INSERT INTO v5sn_nb3_ids VALUES
    (250001,201781),(250002,201784),(250003,201783),(250004,201782),(250005,201785),(250006,201786),
    (150001,102350),(150002,102349),(150003,102356),(150004,102361),(150005,102354),(150006,102364),
    (150007,102365),(150008,102359),(150009,102353),(150010,102351),(150011,102352),(150012,102360),
    (150013,102358),(150014,102362),(150015,102363),(150016,102355);
UPDATE deck_card_history h JOIN v5sn_nb3_ids m ON h.card_id = m.old_id
SET h.card_id = m.new_id
WHERE h.creation_date <= (SELECT installed_on FROM flyway_schema_history WHERE version = '1.0.70' AND success = 1);

-- Seed official catalog IDs before the asynchronous CSV import and initial deck indexing.
-- Temporary copies avoid disabling the translation foreign keys.
CREATE TEMPORARY TABLE v5sn_crypt ENGINE=InnoDB AS
SELECT c.* FROM crypt c JOIN v5sn_ids m ON c.id = m.old_id;
UPDATE v5sn_crypt c JOIN v5sn_ids m ON c.id = m.old_id
SET c.id = m.new_id, c.name = m.card_name, c.`set` = m.card_set;
INSERT INTO crypt SELECT * FROM v5sn_crypt ON DUPLICATE KEY UPDATE id = crypt.id;
CREATE TEMPORARY TABLE v5sn_library ENGINE=InnoDB AS
SELECT c.* FROM library c JOIN v5sn_ids m ON c.id = m.old_id;
UPDATE v5sn_library c JOIN v5sn_ids m ON c.id = m.old_id
SET c.id = m.new_id, c.name = m.card_name, c.`set` = m.card_set;
INSERT INTO library SELECT * FROM v5sn_library ON DUPLICATE KEY UPDATE id = library.id;
UPDATE crypt c JOIN v5sn_ids m ON c.id = m.new_id
SET c.`set` = m.card_set, c.modification_date = c.modification_date;
UPDATE library c JOIN v5sn_ids m ON c.id = m.new_id
SET c.`set` = m.card_set, c.modification_date = c.modification_date;
INSERT INTO `set` (id,abbrev,release_date,full_name,company)
VALUES (399987,'V5SN','2026-10-31','Fifth Edition (SoNY & NBr)','Paradox Interactive AB') AS official_set
ON DUPLICATE KEY UPDATE abbrev = official_set.abbrev, release_date = official_set.release_date,
    full_name = official_set.full_name, company = official_set.company;

-- Relational card IDs. Existing metadata, quantities and timestamps are retained.
UPDATE deck_card c JOIN v5sn_ids m ON c.id = m.old_id
SET c.id = m.new_id, c.modification_date = c.modification_date;
UPDATE deck_card_history c JOIN v5sn_ids m ON c.card_id = m.old_id SET c.card_id = m.new_id;
UPDATE card_errata c JOIN v5sn_ids m ON c.card_id = m.old_id
SET c.card_id = m.new_id, c.modification_date = c.modification_date;
UPDATE vtesdle_day c JOIN v5sn_ids m ON c.card_id = m.old_id SET c.card_id = m.new_id;

UPDATE collection_card c JOIN v5sn_ids m ON c.card_id IN (m.old_id,m.new_id)
SET c.card_id = m.new_id,
    c.`set` = CASE WHEN c.`set` = 'Spoiler' THEN 'V5SN' ELSE c.`set` END,
    c.modification_date = c.modification_date;

UPDATE collection_card_history c JOIN v5sn_ids m ON c.card_id IN (m.old_id,m.new_id)
SET c.card_id = m.new_id,
    c.`set` = CASE WHEN c.`set` = 'Spoiler' THEN 'V5SN' ELSE c.`set` END;

UPDATE wishlist_card c JOIN v5sn_ids m ON c.card_id IN (m.old_id,m.new_id)
SET c.card_id = m.new_id,
    c.`set` = CASE WHEN c.`set` = 'Spoiler' THEN 'V5SN' ELSE c.`set` END,
    c.modification_date = c.modification_date;

-- Shop schedulers will rebuild offers for the official IDs.
DELETE c FROM card_shop c JOIN v5sn_ids m ON c.card_id IN (m.old_id,m.new_id);

UPDATE crypt_i18n c JOIN v5sn_ids m ON c.id = m.old_id
SET c.id = m.new_id, c.image = REPLACE(c.image,CONCAT(m.old_id,'.jpg'),CONCAT(m.new_id,'.jpg')),
    c.modification_date = c.modification_date;

UPDATE library_i18n c JOIN v5sn_ids m ON c.id = m.old_id
SET c.id = m.new_id, c.image = REPLACE(c.image,CONCAT(m.old_id,'.jpg'),CONCAT(m.new_id,'.jpg')),
    c.modification_date = c.modification_date;

-- JSON IDs: exact cardId properties and numeric card keys only.
-- JSON is stored by MySQL with normalized spacing. No replacement of arbitrary prose.

-- Academia de Campeões, São Paulo: 150001 -> 102368
UPDATE deck_archetype SET card_requirements = REGEXP_REPLACE(CAST(card_requirements AS CHAR), '"cardId": 150001(?=[,}])', '"cardId": 102368'), modification_date = modification_date WHERE JSON_CONTAINS(card_requirements, '{"cardId":150001}');
UPDATE limited_format SET `format` = REPLACE(CAST(`format` AS CHAR), '"150001":', '"102368":'), modification_date = modification_date WHERE CAST(`format` AS CHAR) LIKE '%"150001":%';
UPDATE deck SET extra = JSON_SET(extra, '$.limitedFormat', CAST(REPLACE(CAST(JSON_EXTRACT(extra, '$.limitedFormat') AS CHAR), '"150001":', '"102368":') AS JSON)), modification_date = modification_date WHERE CAST(JSON_EXTRACT(extra, '$.limitedFormat') AS CHAR) LIKE '%"150001":%';
UPDATE user_search_preset SET params = JSON_MERGE_PATCH(params, JSON_OBJECT(
    'cards', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cards')), '(?<![0-9])150001(?![0-9])', '102368'),
    'excludedCards', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.excludedCards')), '(?<![0-9])150001(?![0-9])', '102368'),
    'cardId', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cardId')), '(?<![0-9])150001(?![0-9])', '102368'),
    'cardIds', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cardIds')), '(?<![0-9])150001(?![0-9])', '102368')
)), modification_date = modification_date WHERE JSON_EXTRACT(params, '$.cards', '$.excludedCards', '$.cardId', '$.cardIds') REGEXP '(?<![0-9])150001(?![0-9])';

