UPDATE limited_format SET `format` = REPLACE(CAST(`format` AS CHAR), '"250028":', '"201823":'), modification_date = modification_date WHERE CAST(`format` AS CHAR) LIKE '%"250028":%';
UPDATE deck SET extra = JSON_SET(extra, '$.limitedFormat', CAST(REPLACE(CAST(JSON_EXTRACT(extra, '$.limitedFormat') AS CHAR), '"250028":', '"201823":') AS JSON)), modification_date = modification_date WHERE CAST(JSON_EXTRACT(extra, '$.limitedFormat') AS CHAR) LIKE '%"250028":%';
UPDATE user_search_preset SET params = JSON_MERGE_PATCH(params, JSON_OBJECT(
    'cards', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cards')), '(?<![0-9])250028(?![0-9])', '201823'),
    'excludedCards', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.excludedCards')), '(?<![0-9])250028(?![0-9])', '201823'),
    'cardId', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cardId')), '(?<![0-9])250028(?![0-9])', '201823'),
    'cardIds', REGEXP_REPLACE(JSON_UNQUOTE(JSON_EXTRACT(params,'$.cardIds')), '(?<![0-9])250028(?![0-9])', '201823')
)), modification_date = modification_date WHERE JSON_EXTRACT(params, '$.cards', '$.excludedCards', '$.cardId', '$.cardIds') REGEXP '(?<![0-9])250028(?![0-9])';

