-- Limited formats referring to this release's former Spoiler set.
UPDATE limited_format SET `format` = JSON_REMOVE(JSON_SET(`format`, '$.sets.V5SN', JSON_EXTRACT(`format`, '$.sets.Spoiler')), '$.sets.Spoiler'), modification_date = modification_date WHERE JSON_CONTAINS_PATH(`format`, 'one', '$.sets.Spoiler');
UPDATE deck SET extra = JSON_REMOVE(JSON_SET(extra, '$.limitedFormat.sets.V5SN', JSON_EXTRACT(extra, '$.limitedFormat.sets.Spoiler')), '$.limitedFormat.sets.Spoiler'), modification_date = modification_date WHERE JSON_CONTAINS_PATH(extra, 'one', '$.limitedFormat.sets.Spoiler');

UPDATE deck SET `set` = 'V5SN:NBr', modification_date = modification_date WHERE id = 'preconstructed-noites_brasileiras';
UPDATE deck SET `set` = 'V5SN:SoNY', modification_date = modification_date WHERE id = 'preconstructed-secrets_of_new_york';

DELETE c FROM crypt c JOIN v5sn_ids m ON c.id = m.old_id;
DELETE c FROM library c JOIN v5sn_ids m ON c.id = m.old_id;

-- Remove only history generated by the updates above, never the pre-existing history.
-- This is why all other application writers must be stopped while the script runs.
DELETE h FROM deck_card_history h JOIN v5sn_ids m ON h.card_id IN (m.old_id,m.new_id)
WHERE h.id > @v5sn_deck_history_start;
DELETE h FROM collection_card_history h JOIN v5sn_ids m ON h.card_id IN (m.old_id,m.new_id)
WHERE h.id > @v5sn_collection_history_start;

DROP TEMPORARY TABLE v5sn_crypt, v5sn_library, v5sn_nb3_ids, v5sn_ids;
SET @v5sn_deck_history_start = NULL, @v5sn_collection_history_start = NULL;
